// TestListFileNameForGolden checks every name `apt-get update` gave a file in
// testdata/sources/listnames/expected.tsv (regenerated by generate.sh in the
// same directory) against ListFileNameFor of the sources.list line it came
// from.
func TestListFileNameForGolden(t *testing.T) {
	t.Parallel()

	f, err := os.Open(filepath.Join("testdata", "sources", "listnames", "expected.tsv"))
	require.NoError(t, err)

	defer func() { _ = f.Close() }()

	rows := 0
	seenRel := make(map[string]bool)

	sc := bufio.NewScanner(f)
	for sc.Scan() {
		cols := strings.Split(sc.Text(), "\t")
		require.Len(t, cols, 3, sc.Text())

		line, rel, want := cols[0], cols[1], cols[2]

		srcs, err := ParseSourcesList(line)
		require.NoError(t, err, line)
		require.Len(t, srcs, 1, line)

		got := ListFileNameFor(&srcs[0], rel)
		assert.Equal(t, want, got, "%s: %s", line, rel)

		seenRel[rel] = true

		// The legacy entry point agrees, and the prefix is what BaseURLs
		// keys on.
		assert.Equal(t, want, ListFileName(srcs[0].URL, srcs[0].Suite, rel))

		if !srcs[0].Flat() {
			prefix, _, found := strings.Cut(want, "_dists_")
			require.True(t, found, want)
			assert.Equal(t, srcs[0].URL, BaseURLs(srcs)[prefix], "%s: %s", line, prefix)
		}

		rows++
	}

	require.NoError(t, sc.Err())
	assert.Greater(t, rows, 60)

	for _, rel := range []string{
		"InRelease", "Release", "Release.gpg", "main/binary-amd64/Packages", "main/source/Sources",
		"main/i18n/Translation-en", "main/Contents-amd64", "Packages", "Contents-amd64",
	} {
		assert.True(t, seenRel[rel], "golden file covers %s", rel)
	}
}

func TestParseAptURI(t *testing.T) {
	t.Parallel()

	tests := []struct {
		raw  string
		want aptURI
		ok   bool
	}{
		{"http://h/p", aptURI{access: "http", host: "h", path: "/p"}, true},
		{"http://h", aptURI{access: "http", host: "h", path: "/"}, true},
		{"http://h:8080/p/q/", aptURI{access: "http", host: "h", port: 8080, path: "/p/q/"}, true},
		{"https://u:p%40w@h:443/x", aptURI{access: "https", user: "u", password: "p@w", host: "h", port: 443, path: "/x"}, true},
		{"https://user@h/x", aptURI{access: "https", user: "user", host: "h", path: "/x"}, true},
		{"http://[::1]:8081/v6", aptURI{access: "http", host: "::1", port: 8081, path: "/v6"}, true},
		{"http://[2001:db8::1]/x", aptURI{access: "http", host: "2001:db8::1", path: "/x"}, true},
		{"file:/srv/x", aptURI{access: "file", path: "/srv/x"}, true},
		{"file:///srv/x", aptURI{access: "file", path: "/srv/x"}, true},
		{"copy:/srv/x", aptURI{access: "copy", path: "/srv/x"}, true},
		{"cdrom:[Debian 12]/", aptURI{access: "cdrom", host: "Debian 12", path: "/"}, true},
		{"http://h:99999999999999999999/", aptURI{access: "http", host: "h", port: 1 << 31, path: "/"}, true},
		{"http://h:abc/", aptURI{access: "http", host: "h", path: "/"}, true},
		{"http://[::1", aptURI{access: "http", path: "/"}, false},
		{"noscheme", aptURI{access: "noscheme", path: "/"}, false},
	}

	for _, tt := range tests {
		got, ok := parseAptURI(tt.raw)
		assert.Equal(t, tt.ok, ok, tt.raw)

		if tt.ok {
			assert.Equal(t, tt.want, got, tt.raw)
		}
	}
}

func TestDequote(t *testing.T) {
	t.Parallel()

	assert.Equal(t, "plain", dequote("plain"))
	assert.Equal(t, "a@b", dequote("a%40b"))
	assert.Equal(t, "a%zzb", dequote("a%zzb"))
	assert.Equal(t, "a%4", dequote("a%4"))
	assert.Equal(t, "A", dequote("%41"), "an escape that ends the string")
}

func TestQuoteString(t *testing.T) {
	t.Parallel()

	assert.Equal(t, "a%20b%25c%7ed%c3%a9", quoteString("a b%c~d\u00e9", "~"))
	assert.Equal(t, "ok-+.,:;()", quoteString("ok-+.,:;()", ""))
	assert.Equal(t, "%00%7f", quoteString("\x00\x7f", ""))
}

func TestListFileName(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name, url, suite, rel, want string
	}{
		{"plain", "https://archive.ubuntu.com/ubuntu/", "jammy", "main/binary-amd64/Packages.xz", "archive.ubuntu.com_ubuntu_dists_jammy_main_binary-amd64_Packages.xz"},
		{"no trailing slash", "https://archive.ubuntu.com/ubuntu", "jammy", "InRelease", "archive.ubuntu.com_ubuntu_dists_jammy_InRelease"},
		{"root path", "http://h", "s", "Release", "h_dists_s_Release"},
		{"credentials dropped", "http://u:p@h/x/", "s", "Release", "h_x_dists_s_Release"},
		{"port kept", "http://h:80/x/", "s", "Release", "h:80_x_dists_s_Release"},
		{"port zero dropped", "http://h:0/x/", "s", "Release", "h_x_dists_s_Release"},
		{"file", "file:/srv/r/", "s", "Release", "_srv_r_dists_s_Release"},
		{"file with slashes", "file:///srv/r/", "s", "Release", "_srv_r_dists_s_Release"},
		{"underscore and tilde", "http://h/a_b~c/", "s", "Release", "h_a%5fb%7ec_dists_s_Release"},
		{"suite plus", "http://h/", "a+b", "Release", "h_dists_a%252bb_Release"},
		{"flat dot", "http://h/r/", "./", "Packages", "h_r_._Packages"},
		{"flat root", "http://h/r/", "/", "Packages", "h_r_Packages"},
		{"flat subdir", "http://h/r/", "x/y/", "Packages", "h_r_x_y_Packages"},
		{"unicode", "http://h/\u00e9/", "s", "Release", "h_%c3%a9_dists_s_Release"},
		{"no scheme", "%zz", "s", "x", ""},
		{"open bracket", "http://[::1", "s", "x", ""},
		{"empty", "", "", "", ""},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			assert.Equal(t, tt.want, ListFileName(tt.url, tt.suite, tt.rel))
			assert.Equal(t, tt.want, ListFileNameFor(&Source{URL: tt.url, Suite: tt.suite}, tt.rel))
		})
	}
}

func TestEncodeHostPath(t *testing.T) {
	t.Parallel()

	assert.Equal(t, "archive.ubuntu.com_ubuntu", encodeHostPath("https://archive.ubuntu.com/ubuntu/"))
	assert.Equal(t, "archive.ubuntu.com_ubuntu", encodeHostPath("https://archive.ubuntu.com/ubuntu"))
	assert.Equal(t, "h", encodeHostPath("http://h"))
	assert.Equal(t, "_srv_r", encodeHostPath("file:///srv/r"))
	assert.Equal(t, "h:8080_a%5fb", encodeHostPath("http://u:p@h:8080/a_b/"))
	assert.Empty(t, encodeHostPath("nothing"))
	assert.Empty(t, encodeHostPath("http://[::1"))
}

func TestBaseURLsKeys(t *testing.T) {
	t.Parallel()

	got := BaseURLs([]Source{
		{URL: "https://a.example/debian/"},
		{URL: "http://b.example:81/x/y"},
		{URL: "https://a.example/debian/"},
		{URL: "junk"},
		{URL: "file:/srv/r/"},
	})

	assert.Equal(t, map[string]string{
		"a.example_debian": "https://a.example/debian/",
		"b.example:81_x_y": "http://b.example:81/x/y",
		"_srv_r":           "file:/srv/r/",
	}, got)
}
